class Solution {
public:
    bool checkValidGrid(std::vector<std::vector<int>>& grid) {
        if (grid[0][0] != 0) return false;
        int n = grid.size();
        std::vector<std::pair<int, int>> pos(n * n);
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                pos[grid[r][c]] = {r, c};
            }
        }
        for (int k = 0; k < n * n - 1; ++k) {
            int dr = std::abs(pos[k + 1].first - pos[k].first);
            int dc = std::abs(pos[k + 1].second - pos[k].second);
            if (!((dr == 1 && dc == 2) || (dr == 2 && dc == 1))) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean checkValidGrid(int[][] grid) {
        if (grid[0][0] != 0) return false;
        int n = grid.length;
        int[][] pos = new int[n * n][2];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                pos[grid[r][c]][0] = r;
                pos[grid[r][c]][1] = c;
            }
        }
        for (int k = 0; k < n * n - 1; k++) {
            int dr = Math.abs(pos[k + 1][0] - pos[k][0]);
            int dc = Math.abs(pos[k + 1][1] - pos[k][1]);
            if (!((dr == 1 && dc == 2) || (dr == 2 && dc == 1))) {
                return false;
            }
        }
        return true;
    }
}

var checkValidGrid = function(grid) {
    if (grid[0][0] !== 0) return false;
    const n = grid.length;
    const pos = new Array(n * n);
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            pos[grid[r][c]] = [r, c];
        }
    }
    for (let k = 0; k < n * n - 1; k++) {
        const dr = Math.abs(pos[k + 1][0] - pos[k][0]);
        const dc = Math.abs(pos[k + 1][1] - pos[k][1]);
        if (!((dr === 1 && dc === 2) || (dr === 2 && dc === 1))) {
            return false;
        }
    }
    return true;
};
